mapper.select:
SELECT I.IF_CODE , I.IF_NAME , I.ATTRIBUTE01 AS SHEET_NAME FROM INTERFACE_ITEM_MST I JOIN INTERFACE_SCHEDULE_MAPPING M ON M.IF_CODE = I.IF_CODE AND M.COMPANY_CODE = I.COMPANY_CODE WHERE I.COMPANY_CODE = #{company_code} AND M.SCHEDULE_CODE = #{schedule_code}
AND M.IF_CODE = #{if_code}
AND I.USING_YN = 'Y' AND TRIM(COALESCE(I.EXCEL_UPLOAD_YN, 'N')) = 'Y' ORDER BY M.SCHEDULE_SEQ

SELECT S.EXECUTION_PROGRAM
  FROM INTERFACE_SCHEDULE S
 WHERE S.SCHEDULE_CODE = #{schedule_code}
   AND S.COMPANY_CODE = #{company_code}
 LIMIT 1

SELECT T.INTG_INTERFACE_TRANS_ID , T.IF_CODE , COALESCE(I.IF_NAME, T.IF_CODE) AS IF_NAME , T.TOTAL_ROWS , COALESCE(E.ERROR_COUNT, 0) AS ERROR_COUNT , TO_CHAR(T.START_TIME, 'YYYY-MM-DD HH24:MI:SS') AS START_TIME , T.STATUS , CASE WHEN T.STATUS = 'S' THEN 'Y' ELSE 'N' END AS SUBMIT_YN , TO_CHAR(T.TRANS_DATE, 'YYYY-MM-DD HH24:MI:SS') AS TRANS_DATE , T.ERROR_MESSAGE FROM INTG_INTERFACE_TRANS T LEFT JOIN INTERFACE_ITEM_MST I ON I.IF_CODE = T.IF_CODE AND I.COMPANY_CODE = T.COMPANY_CODE LEFT JOIN ( SELECT INTG_INTERFACE_TRANS_ID , COUNT(*) FILTER (WHERE ERROR_YN = 'Y') AS ERROR_COUNT FROM INTG_INTERFACE_TRANS_DTL GROUP BY INTG_INTERFACE_TRANS_ID ) E ON E.INTG_INTERFACE_TRANS_ID = T.INTG_INTERFACE_TRANS_ID WHERE T.COMPANY_CODE = #{company_code} AND T.INTERFACE_TYPE = 'EXCEL'
AND T.SCHEDULE_CODE = #{schedule_code}
AND T.IF_PARAM ILIKE CONCAT('%BaseYYYYMM=', #{base_yyyymm}, '%')
AND T.IF_CODE = #{if_code}
ORDER BY T.TRANS_DATE, T.INTG_INTERFACE_TRANS_ID

SELECT T.INTG_INTERFACE_TRANS_ID , T.IF_CODE , COALESCE(I.IF_NAME, T.IF_CODE) AS IF_NAME , T.TOTAL_ROWS , T.TRANS_STATUS , CASE T.TRANS_STATUS WHEN '0' THEN 'running' WHEN '1' THEN 'succeed' WHEN '2' THEN 'failed' ELSE T.TRANS_STATUS END AS TRANS_STATUS_NAME , TO_CHAR(T.START_TIME, 'YYYY-MM-DD HH24:MI:SS') AS START_TIME , TO_CHAR(T.TRANS_DATE, 'YYYY-MM-DD HH24:MI:SS') AS TRANS_DATE , T.IF_PARAM , T.ERROR_MESSAGE FROM INTG_INTERFACE_TRANS T LEFT JOIN INTERFACE_ITEM_MST I ON I.IF_CODE = T.IF_CODE AND I.COMPANY_CODE = T.COMPANY_CODE WHERE T.COMPANY_CODE = #{company_code} AND COALESCE(T.INTERFACE_TYPE, '') <> 'EXCEL'
AND T.SCHEDULE_CODE = #{schedule_code}
AND T.IF_PARAM ILIKE CONCAT('%', #{base_yyyymm}, '%')
AND T.IF_CODE = #{if_code}
ORDER BY T.TRANS_DATE DESC, T.INTG_INTERFACE_TRANS_ID DESC

mapper.update:
UPDATE INTERFACE_SCHEDULE
   SET STATUS = '0'
     , EXTCUTION_MESSAGE = NULL
     , UPDATE_DATE = NOW()
     , UPDATE_BY = #{update_by}
 WHERE SCHEDULE_CODE = #{schedule_code}
   AND COMPANY_CODE = #{company_code}
